using System;using System.Linq;using System.Text;using System.Xml;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 BillQuantity ExtraPayQuantity(string section,string code,string description,double quantity,string unit,string source,string computation){var target=BackupPayItemCatalog.Items().FirstOrDefault(t=>t.Code==code&&(description==null||t.Description==description));var item=extraSiteQuantities.FirstOrDefault(q=>q.Section==section&&q.PayCode==code&&q.Description==(description??(target==null?code:target.Description))&&q.Unit==unit);if(item==null){item=new BillQuantity{Section=section,Description=description??(target==null?code:target.Description),Quantity=0,Unit=unit,PayCode=code,PayDescription=description??(target==null?"":target.Description)};extraSiteQuantities.Add(item);}item.Quantity+=quantity;item.Sources.Add(new BillQuantity{Description=source,Quantity=quantity,Unit=unit,Computation=computation});return item;}
 void RecalculateSiteRow(ExtraWorkGrid item,DataGridViewRow row){string source=item.Kind+" "+Cell(row,0)+" | "+Cell(row,1);double quantity;
  if(item.Key=="Trees"){
   string code=SiteWorkTakeoff.TreeItem(Number(row,2));row.Cells[4].Value=code;row.Cells[5].Value=1;ExtraPayQuantity("Earthworks",code,null,1,"ea",source,"Measured diameter "+Cell(row,2)+"mm; one included Tree ID = one tree");
  }else if(item.Key=="Clearing"){
   if(Cell(row,5)=="Direct total area"){quantity=Number(row,6);if(quantity<=0)throw new Exception("Enter a positive directly measured total area.");if(Cell(row,2)!=""||Cell(row,3)!="")throw new Exception("Use dimensions OR direct total area, not both.");}
   else {if(Cell(row,6)!="")throw new Exception("Clear Direct total area when using dimensions.");quantity=SiteWorkTakeoff.Area(Number(row,2),Number(row,3),Count(row,4));}
   row.Cells[7].Value=quantity;ExtraPayQuantity("Earthworks","800(1)",null,quantity,"m2",source,Cell(row,5)=="Direct total area"?"Entered total area = "+quantity.ToString("R",CultureInfo.InvariantCulture)+"m2":"L × W × qty = "+Cell(row,2)+" × "+Cell(row,3)+" × "+Cell(row,4));
  }else if(item.Key=="SlopeFill"){
   double installed=SiteWorkTakeoff.Rectangular(Number(row,2),Number(row,3),Number(row,4),Count(row,5));quantity=installed*(1+(double)gravelAllowance.Value/100);row.Cells[6].Value=installed;row.Cells[7].Value=quantity;ExtraPayQuantity("Slope Protection Works","103(3)",null,quantity,"m3",source,"Installed L × W × t × qty = "+installed.ToString("R",CultureInfo.InvariantCulture)+"m3; purchase = installed × (1 + "+gravelAllowance.Value+"% gravel purchase allowance)");
  }else if(item.Key=="SlopeStone"){
   quantity=SiteWorkTakeoff.Stone(Number(row,2),Number(row,3),Number(row,4),Number(row,5),Count(row,6));row.Cells[7].Value=quantity;ExtraPayQuantity("Slope Protection Works","506(1)",null,quantity,"m3",source,"L × H × (top width + bottom width) / 2 × qty = "+Cell(row,2)+" × "+Cell(row,3)+" × ("+Cell(row,4)+" + "+Cell(row,5)+") / 2 × "+Cell(row,6));
  }else{
   int index=int.Parse(item.Key.Substring("Pavement".Length));double area=SiteWorkTakeoff.Area(Number(row,2),Number(row,3),Count(row,5));double thickness=index==3?150:index==4?230:index==5?100:index==1?0:Number(row,4);if(index>=3)row.Cells[4].Value=thickness;
   double volume=index==1?0:SiteWorkTakeoff.Rectangular(Number(row,2),Number(row,3),thickness,Count(row,5));string unit,code,description=null;
   if(index==0){code="102(2)";quantity=volume;unit="m3";}else if(index==1){code="105(1)a";unit="m2";quantity=area;}
   else if(index==2){bool baseCourse=Cell(row,6)=="Aggregate Base Course";code=baseCourse?"201(1)":"200(1)";description=baseCourse?"Aggregate Base Course":null;quantity=volume;unit="m3";}
   else{code=index==3?"311(1)a":index==4?"311(1)c1":"601(1)";quantity=area;unit="m2";}
   row.Cells[7].Value=quantity;row.Cells[8].Value=unit;row.Cells[9].Value=index>=3?volume:0;ExtraPayQuantity("Pavement Construction",code,description,quantity,unit,source,index==1?"Prepared area = L × W × qty = "+area.ToString("R",CultureInfo.InvariantCulture)+"m2; no swell/shrink factor.":(index==0?"In-place bank excavation; no swell/shrink factor. ":"")+"L × W × qty = "+area.ToString("R",CultureInfo.InvariantCulture)+"m2; depth/thickness "+thickness.ToString("R",CultureInfo.InvariantCulture)+"mm; volume = "+volume.ToString("R",CultureInfo.InvariantCulture)+"m3. Pay quantity uses "+unit+(index>=3?"; reference concrete volume is not added to structural concrete":""));
  }
  row.Cells[item.Grid.Columns.Count-1].Value="Estimated";
 }
 List<BillQuantity> ExtraBillQuantities(){var list=new List<BillQuantity>(extraSiteQuantities);var waterproofing=SlabWaterproofingQuantity();if(waterproofing!=null)list.Add(waterproofing);list.AddRange(RailingQuantities());
  foreach(var group in miscQuantities.GroupBy(q=>q.Kind)){var concrete=new BillQuantity{Section=group.Key=="Column Estimate"?"Reinforced Concrete Works":"Miscellaneous Structures",Description=group.Key+" concrete",Unit="m3",Quantity=group.Sum(q=>q.Concrete)};var forms=new BillQuantity{Section=group.Key=="Column Estimate"?"Reinforced Concrete Works":"Miscellaneous Structures",Description=group.Key+" forms",Unit="m2",Quantity=group.Sum(q=>q.Forms),PayCode="903(2)",PayDescription="Formworks and Falseworks"};foreach(var q in group){concrete.Sources.Add(new BillQuantity{Description=q.Kind+" "+q.Id+" | "+q.Description,Quantity=q.Concrete,Unit="m3"});forms.Sources.Add(new BillQuantity{Description=q.Kind+" "+q.Id+" | "+q.Description,Quantity=q.Forms,Unit="m2"});}list.Add(concrete);list.Add(forms);}
  if(wallFootingResults.Count>0){var forms=new BillQuantity{Section="Wall Footing",Description="Wall footing forms",Unit="m2",Quantity=wallFootingResults.Sum(q=>q.Forms),PayCode="903(2)",PayDescription="Formworks and Falseworks"};forms.Sources.AddRange(wallFootingResults.Select(q=>new BillQuantity{Description="Wall footing "+q.Id+" | "+q.Description,Quantity=q.Forms,Unit="m2"}));list.Add(forms);}
  if(slopeQuantities.Count>0){var concrete=new BillQuantity{Section="Slope Protection Works",Description="Concrete Slope Protection",Unit="m3",PayCode="510(2)",PayDescription="Concrete Slope Protection",Quantity=slopeQuantities.Sum(q=>q.Concrete)};var forms=new BillQuantity{Section="Slope Protection Works",Description="Slope RC formworks",Unit="m2",PayCode="903(2)",PayDescription="Formworks and Falseworks",Quantity=slopeQuantities.Sum(q=>q.Forms)};foreach(var q in slopeQuantities){concrete.Sources.Add(new BillQuantity{Description=q.Kind+" "+q.Id+" | "+q.Description,Quantity=q.Concrete,Unit="m3"});forms.Sources.Add(new BillQuantity{Description=q.Kind+" "+q.Id+" | "+q.Description,Quantity=q.Forms,Unit="m2"});}list.Add(concrete);list.Add(forms);}
  var steel=new BillQuantity{Section="Slope Protection Works",Description="Reinforcing Steel, Grade 40",Unit="kg",PayCode="404(1)a",PayDescription="Reinforcing Steel, Grade 40",Quantity=slopePlan.Sum(a=>a.Purchase)};foreach(var a in slopePlan)steel.Sources.Add(new BillQuantity{Description=RebarSource(a),Quantity=a.Purchase,Unit="kg"});if(slopePlan.Count>0)list.Add(steel);return list;
 }
 void AddExtraExcelRows(List<object[]> rebar,List<WorksExcelTable> tables){foreach(var a in miscPlan.Concat(wallFootingPlan))rebar.Add(new object[]{"Miscellaneous Structures",a.Entry.Description,a.Entry.Beam,"Manual miscellaneous structure",a.Demand.Grade,a.Demand.Diameter,a.Net,0,0,a.Splice+a.Waste,a.Purchase,0,int.Parse(a.Entry.Quantity)});var rows=miscQuantities.Concat(slopeQuantities).Select(q=>new object[]{q.Kind,q.Id,q.Description,q.Quantity,q.Fc,q.Concrete,q.Forms,q.Steel.Result.Total,(slopeQuantities.Contains(q)?slopePlan:miscPlan).Where(a=>a.Entry==q.Steel).Sum(a=>a.Purchase)}).ToList();tables.Add(new WorksExcelTable("POW Misc Slope Details",new[]{"Member type","ID","Description","Qty","Concrete MPa","Concrete m3","Forms m2","Rebar net kg","Rebar purchase kg"},rows));tables.Add(new WorksExcelTable("POW Site Pavement Totals",new[]{"Pay item description","Quantity","Unit"},extraSiteQuantities.Select(q=>new object[]{q.Description,q.Quantity,q.Unit}).ToList()));}
 void WriteExtraSettings(XmlElement root){if(!extraReady)return;WriteFootingInputMethods(root);if(columnOpenHooks!=null)root.SetAttribute("columnOpenHooks",columnOpenHooks.Text);root.SetAttribute("leanThicknessMm",leanThickness.Value.ToString(CultureInfo.InvariantCulture));root.SetAttribute("extraStock",CommercialBars.FormatLengths(miscStock));root.SetAttribute("excavationMaterial",excavationMaterial.Text);root.SetAttribute("subgradeUnit",subgradeUnit.Text);foreach(var pair in readyMixGroups)root.SetAttribute("readyMix"+pair.Key,pair.Value.Checked.ToString());foreach(var pair in extraMaterials){string key=pair.Key.Replace(" ","");var m=pair.Value;root.SetAttribute("extraFc"+key,m.Fc.Text);root.SetAttribute("extraSmall"+key,m.Small.Text);root.SetAttribute("extraLarge"+key,m.Large.Text);root.SetAttribute("extraCover"+key,m.Cover.Value.ToString(CultureInfo.InvariantCulture));root.SetAttribute("extraOffset"+key,m.Offset.Value.ToString(CultureInfo.InvariantCulture));}}
 void ReadExtraSettings(XmlElement root){if(extraMaterials.Count==0||excavationMaterial==null)return;ReadFootingInputMethods(root);if(columnOpenHooks!=null&&root.HasAttribute("columnOpenHooks")){string value=root.GetAttribute("columnOpenHooks");if(!columnOpenHooks.Items.Contains(value))throw new Exception("Invalid saved open-tie hooks.");columnOpenHooks.SelectedItem=value;}if(root.HasAttribute("leanThicknessMm"))leanThickness.Value=decimal.Parse(root.GetAttribute("leanThicknessMm"),CultureInfo.InvariantCulture);miscStock=CommercialBars.ParseLengths(root.GetAttribute("extraStock"));foreach(var pair in readyMixGroups)pair.Value.Checked=root.HasAttribute("readyMix"+pair.Key)&&bool.Parse(root.GetAttribute("readyMix"+pair.Key));foreach(var pair in extraMaterials){string key=pair.Key.Replace(" ","");var m=pair.Value;foreach(var box in new[]{new{Box=m.Fc,Name="extraFc"},new{Box=m.Small,Name="extraSmall"},new{Box=m.Large,Name="extraLarge"}})if(root.HasAttribute(box.Name+key)){string value=root.GetAttribute(box.Name+key);if(!box.Box.Items.Contains(value))throw new Exception("Invalid saved miscellaneous/slope material setting.");box.Box.SelectedItem=value;}foreach(var numeric in new[]{new{Box=m.Cover,Name="extraCover"},new{Box=m.Offset,Name="extraOffset"}})if(root.HasAttribute(numeric.Name+key)){decimal value=decimal.Parse(root.GetAttribute(numeric.Name+key),CultureInfo.InvariantCulture);if(value<numeric.Box.Minimum||value>numeric.Box.Maximum)throw new Exception("Invalid saved cover/tie offset.");numeric.Box.Value=value;}}foreach(var option in new[]{new{Box=excavationMaterial,Name="excavationMaterial"},new{Box=subgradeUnit,Name="subgradeUnit"}})if(root.HasAttribute(option.Name)){string value=root.GetAttribute(option.Name);if(option.Name=="subgradeUnit"&&(value=="cu.m."||value=="sq.m."))value="sq.m.";if(!option.Box.Items.Contains(value))throw new Exception("Invalid earthwork pay-item setting.");option.Box.SelectedItem=value;}}
 void WriteExtraProject(XmlElement root){WriteExtraSettings(root);WritePadLean(root);var section=root.OwnerDocument.CreateElement("ExtraQuantities");section.SetAttribute("version","1");root.AppendChild(section);foreach(var pair in extraGrids){var table=root.OwnerDocument.CreateElement("Table");table.SetAttribute("key",pair.Key);section.AppendChild(table);foreach(DataGridViewRow row in pair.Value.Grid.Rows)if(!row.IsNewRow&&!Empty(row)){var entry=root.OwnerDocument.CreateElement("Entry");for(int c=0;c<pair.Value.Inputs;c++)entry.SetAttribute("c"+c,Cell(row,c));table.AppendChild(entry);}}}
 void ValidateExtraProject(XmlElement root,bool required){var section=root["ExtraQuantities"];if(section==null){if(required)throw new Exception("Saved project is missing its additional quantity sheets.");return;}if(section.GetAttribute("version")!="1")throw new Exception("Unsupported additional-quantity format.");var names=new HashSet<string>();foreach(XmlElement table in section.SelectNodes("Table")){string key=table.GetAttribute("key");if(!extraGrids.ContainsKey(key)||!names.Add(key)||table.ChildNodes.Count>10000)throw new Exception("Invalid or duplicate additional quantity table.");foreach(XmlElement row in table.SelectNodes("Entry"))for(int c=0;c<extraGrids[key].Inputs;c++)if(!row.HasAttribute("c"+c)&&!(key=="StructuralColumn"&&c>=16))throw new Exception("Incomplete additional quantity input.");}/* Sheets added after a project was saved (structural columns; railing, v1.4.96) are simply empty in older files. */if(required&&extraGrids.Keys.Any(key=>!LaterExtraSheets.Contains(key)&&!names.Contains(key)))throw new Exception("Incomplete additional quantity sheets.");}
 static readonly HashSet<string> LaterExtraSheets=new HashSet<string>(StringComparer.Ordinal){"StructuralColumn","Railing"};
 void ReadExtraProject(XmlElement root){ValidateExtraProject(root,false);bool before=filling;filling=true;try{foreach(var item in extraGrids.Values)item.Grid.Rows.Clear();ReadExtraSettings(root);ReadFootingInputMethods(root);ReadPadLean(root);var section=root["ExtraQuantities"];if(section!=null)foreach(XmlElement table in section.SelectNodes("Table")){var item=extraGrids[table.GetAttribute("key")];foreach(XmlElement entry in table.SelectNodes("Entry")){int n=item.Grid.Rows.Add();for(int c=0;c<item.Inputs;c++){string value=entry.GetAttribute("c"+c);if(item.Key=="StructuralColumn"&&!entry.HasAttribute("c16")&&(c==8||c==9)&&entry.GetAttribute("c9")=="0")value="";item.Grid.Rows[n].Cells[c].Value=item.Grid.Columns[c] is DataGridViewCheckBoxColumn?(object)(value!=""&&bool.Parse(value)):value;}}}ReadFootingInputMethods(root);InitializePayItemCatalogue();}finally{filling=before;}}
}
}
